"""Build French codex and illustrated receipt from actual contracts/results.
Images are embedded byte-for-byte from Chromium; diagrams are explicitly plans."""
from pathlib import Path
import json,re,html,base64,hashlib
R=Path(__file__).resolve().parent.parent
J=lambda p:json.loads((R/p).read_text());e=lambda s:html.escape(str(s))
C=J('report/CONTRATS_LEVEL_DESIGN_V111.json');B=J('report/browser-results-v111.json');D=J('report/lighting-drive-v111.json')
assert all(t['ok'] for t in B['tests']) and not B['pageErrors'] and not B['consoleErrors'];assert B['htmlSha256']==hashlib.sha256((R/'JOUER_ALIENS_V111.html').read_bytes()).hexdigest()
node=int(re.search(r'# pass (\d+)',(R/'report/node-tests-v111.txt').read_text()).group(1))
STYLE='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0a1219;color:#c9d7dd;font:16px/1.85 system-ui,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:54px 32px 90px}a{color:#c3ddda}h1{font:400 clamp(42px,6vw,76px)/1.08 Georgia,serif;color:#e9e6d9;max-width:960px;margin:24px 0 28px}h2{font:400 30px/1.3 Georgia,serif;color:#d7e4e7;margin:40px 0 16px;border-top:1px solid #354d5d;padding-top:28px}h3{font-size:19px;color:#d5c6a3;font-weight:500}.kicker{font:11px/1.5 monospace;letter-spacing:.23em;color:#85a9bd;text-transform:uppercase}.lead{font-size:21px;max-width:930px;line-height:1.6}.callout{padding:19px 23px;border-left:3px solid #b49b64;background:#182933;color:#c6d9d9;margin:26px 0}.metrics{display:flex;flex-wrap:wrap;gap:14px}.metric{padding:16px 23px;border:1px solid #35505c;background:#12232e;min-width:158px}.metric strong{font:400 33px Georgia,serif;display:block;color:#d6c7a4}.metric small{font-size:12px;color:#92acb8}nav{display:flex;flex-wrap:wrap;gap:21px;margin:24px 0}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.55;margin:20px 0}th,td{padding:11px;border:1px solid #354b58;text-align:left;vertical-align:top}th{background:#1d3441}tr:nth-child(even){background:#13232d}.rooms{margin-top:28px}.room{border:1px solid #38566a;background:linear-gradient(130deg,#192e3a80,#101e2780);padding:26px;margin:26px 0}.room h2{border:0;padding:0;margin-top:0}.diagram{width:100%;height:auto;background:#101e26;border:1px solid #344e5f}.small{font:12px/1.7 monospace;color:#89a4b2;overflow-wrap:anywhere}figcaption{overflow-wrap:anywhere}figure{margin:30px 0}img{width:100%;height:auto;display:block;border:1px solid #496878}figcaption{font-size:13px;color:#9ab2bd;margin-top:10px}details{border:1px solid #3d5567;background:#11232d;padding:17px;margin:16px 0}summary{cursor:pointer;color:#c8dfe1}input{padding:15px;width:100%;background:#142937;color:#dde9e9;border:1px solid #6e92a1;font:15px system-ui}code,pre{font:12px/1.7 monospace;overflow-wrap:anywhere}pre{background:#0b1c26;padding:18px;white-space:pre-wrap}.hide{display:none}.chip{padding:4px 10px;border:1px solid #4c697b;font-size:11px;color:#b5cfd4}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:720px){main{padding:25px 16px}.room{padding:15px}h1{font-size:40px}.lead{font-size:18px}table{display:block;overflow-x:auto}.two{display:block}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:#222}h1,h2,h3{color:#222}nav,input{display:none}figure,.room{break-inside:avoid}main{padding:0}}'''
def page(title,b,js=''):return f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{STYLE}</style></head><body><main>{b}</main>{js}</body></html>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def metrics(rows):return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{e(n)}</strong><small>{e(t)}</small></div>' for n,t in rows)+'</div>'
def diagram(r):
 out=[f'<svg class="diagram" viewBox="-25 -35 {r["width"]+50} {r["depth"]+90}" xmlns="http://www.w3.org/2000/svg" aria-label="Plan calculé du lieu, pas une capture"><rect x="0" y="0" width="{r["width"]}" height="{r["depth"]}" fill="#10252e" stroke="#608091"/>']
 for b in r['solids']:
  out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="{"#649faa" if b.get("material")=="glass" else "#516876"}" fill-opacity=".65" stroke="#9db2b8"/><text x="{b["x"]+3}" y="{b["z"]+14}" font-size="11" fill="#e3e1c7">{e(b["id"])}</text>')
 for b in r['doors']+r['hatches']:out.append(f'<rect x="{b["x"]}" y="{b["z"]}" width="{b["w"]}" height="{b["d"]}" fill="#b2925655" stroke="#dabd7e"/>')
 for c in r['controls']:
  out.append(f'<circle cx="{c["x"]}" cy="{c["z"]}" r="8" fill="{"#b9dfde" if c["circuit"]=="service" else "#dab981"}"/><text x="{c["x"]+13}" y="{c["z"]+4}" font-size="12" fill="#e3e4ca">{e(c["id"])}</text>')
 for l in r['props']:
  if l['type']=='lamp':out.append(f'<rect x="{l["x"]-10}" y="{l["z"]-4}" width="20" height="8" fill="#d8d7a8"/>')
 for x in r['exits']:out.append(f'<circle cx="{x["x"]}" cy="{x["z"]}" r="14" fill="#172c39" stroke="#98d0c1"/><text x="{max(30,min(1170,x["x"]+15))}" y="{x["z"]-18}" fill="#a3cfc7" font-size="12">{e(x["label"])}</text>')
 return ''.join(out)+'</svg>'
old=(R/'CODEX_LEVEL_DESIGN_V110.md').read_text();rules=[]
for m in re.finditer(r'^### (\d+) — (.+)\n\n([\s\S]*?)(?=\n##|\Z)',old,re.M):
 if int(m[1])<=26:rules.append((m[2],m[3].strip()))
assert len(rules)==26
rules[0]=('Conserver les lieux, rendre le noir jouable','Les huit inspections, sept lieux connectés, cinq objectifs et onze ennemis du catalogue restent identiques. Aucun objectif obligatoire n’est ajouté. Les huit circuits service et leurs treize lampes existaient : V111 relie réellement leur état à la perception, au rendu et aux commandes de terrain.')
new=[
('Un seul circuit, pas deux vérités','Le booléen worlds[room].circuits.service commande les lampes déjà présentes. Il n’existe pas de deuxième registre de lumière qui divergerait au chargement. Le relais réseau de mission n’est pas ce circuit. Couper un service n’ouvre ni ne ferme un sas et ne valide aucun objectif.'),
('Manœuvrer à portée réelle','K ou E au contrôle prépare 0,95 seconde avant inversion. La portée, la visibilité du pupitre, la position initiale et la vie sont contrôlées pendant le geste. Marche, tir, coup reçu ou variation du circuit l’interrompent ; K à nouveau annule. La pause ne termine pas l’action.'),
('Le cône doit utiliser les cloisons du jeu','La torche L est orientée à la souris ou au sens de marche. Portée 520 unités, demi-angle 0,32 radian, reconnaissance de cible éclairée au-delà du seuil 0,24. Les rayons de rendu et le test de lumière interrogent les mêmes volumes opaques. Les rayons restent dans les limites physiques de la pièce.'),
('La torche n’est pas une cape d’invisibilité','Le porteur d’une torche allumée est éclairé près de sa source, même s’il pointe à l’opposé du contact. Un ennemi avec une ligne de vue peut donc le reconnaître. Une lampe éteinte n’efface ni une piste, ni un son récent, ni le désir de forcer un sas.'),
('Le noir réduit la reconnaissance, pas les collisions','Dans une pièce sans service, un contact géométriquement visible reste reconnaissable à 120 unités ou moins. Au-delà, la silhouette doit être éclairée. La même règle s’applique aux Marines en couverture, à la sentinelle et aux Xénos. Corps, balles et portes gardent leurs portées et leurs collisions.'),
('Le verre n’est pas un mur opaque','Une vitre déclarée transparente laisse passer la vue et la lumière, tout en bloquant corps et projectiles selon ses propriétés. Éteindre l’éclairage ne doit pas rendre les balles perméables au verre. Le faisceau n’est pas un projectile destructeur.'),
('Le feu et le travail exposent','Un flash de tir illumine brièvement les alentours pendant 0,18 seconde, rayon maximal 170. Le chalumeau illumine une zone de 105 unités pendant les travaux de sas. Ces sources respectent l’occlusion dans le calcul de reconnaissance. Le rendu lumineux reste une approximation 2D stylisée, pas une illumination globale photoréaliste.'),
('Aucune batterie cachée','La torche est un équipement permanent sans batterie consommable dans cette version. Son arbitrage est la discrétion, pas une nouvelle ressource arbitraire. La coupure locale est gratuite et réversible mais prend du temps. Aucun soin, plaque ou chargeur n’est ajouté par la lumière.'),
('Une reprise doit conserver le noir','Schéma 111 : angle, interrupteur de torche, bilan des manœuvres et action en cours sont validés avant mutation. Les circuits restent dans l’enveloppe du monde déjà validée. V110 est d’abord validée par son propre module ; ses circuits, vies, chargeurs, mémoires et plaques sont conservés exactement.'),
('Afficher l’information sans révéler une cible','Les contrôles L/K et l’état éclairé/ombre partagent la bande du détecteur hors terrain. La carte n’interroge pas les souvenirs ennemis. L’aide à la visée ne sélectionne que des contacts déjà observés ; aucune cible cachée ne doit apparaître parce que le curseur passe sur ses coordonnées.')]
rules+=new
body='<p class="kicker">Tantalus / Aliens 1986 · Codex de level design V111</p><h1>Dans le noir</h1><p class="lead">Le courant, les silhouettes et les chemins appartiennent au même lieu. Le faisceau ne doit pas mentir sur ce que l’on peut voir.</p>'+metrics([(len(rules),'règles de conception'),(8,'fiches de lieux'),(13,'lampes existantes'),('0','nouvelle population')])
body+='<nav><a href="JOUER_ALIENS_V111.html">Jouer</a><a href="RAPPORT_ILLUSTRE_V111.html">Rapport illustré</a><a href="#regles">Règles</a><a href="#lieux">Plans des lieux</a></nav><div class="callout">Branche autonome V110 poursuivie. Ces fiches décrivent les lieux du module livrable, pas une fusion dans les 64 salles natives de Tantalus. Les schémas sont des plans calculés ; ils ne sont pas des captures du jeu.</div><h2 id="regles">Contrats de conception</h2>'
md=['# CODEX LEVEL DESIGN — ALIENS V111 / Dans le noir','\nBranche autonome V110 poursuivie. Aucun raccord natif ni nouveau final.\n','## Règles de conception']
for i,(title,text) in enumerate(rules,1):body+=f'<details><summary>{i:02} — {e(title)}</summary><p>{e(text)}</p></details>';md+=[f'\n### {i:02} — {title}\n',text]
body+='<h2 id="lieux">Huit lieux, une source géométrique</h2><label for="filter">Rechercher un lieu, circuit, appui ou commande</label><input id="filter" placeholder="Operations, service, mur, lampe…"><p id="filter-note">8 lieux affichés</p><div class="rooms">'
for r in C['rooms']:
 lp=next(p for p in C['lightingProfiles'] if p['roomId']==r['id']);body+=f'<article class="room" data-search="{e((r["title"]+" "+r["id"]+" "+json.dumps(r["props"],ensure_ascii=False)).lower())}"><p class="kicker">{e(r["id"])} · {e(r["family"])} · {e(r["mode"])}</p><h2>{e(r["title"])}</h2><p>{e(r["goal"])}</p>'+diagram(r)+'<p class="small">PLAN CALCULÉ · x/z · surfaces physiques, portes ambre, commandes cyan, lampes crème. Pas une capture du renderer.</p>'
 body+=table(['Circuit local','Commande','Lampes sur supports','Portée sombre'],[['service',lp['controlId'],len(lp['lamps']),'120 u en vue directe']])
 body+=table(['Sortie','Destination','Seuil x,z','Arrivée x,z'],[[x['id'],x['to']['room'],f"{x['x']}, {x['z']}",f"{x['to']['arrival']['x']}, {x['to']['arrival']['z']}" ]for x in r['exits']])
 body+=table(['Équipement','Support nommé','x,z','Hauteur d’appui'],[[p['id'],p.get('support','—'),f"{p['x']}, {p['z']}",p.get('elevation',0)]for p in r['props']])
 body+=table(['Volume solide','x,z','w,d','Hauteur','Matériau'],[[p['id'],f"{p['x']}, {p['z']}",f"{p['w']}, {p['d']}",p.get('h','—'),p.get('material','structure')]for p in r['solids']+r['doors']])+'</article>'
 md+=[f'\n## {r["title"]}\n',f'{r["id"]} — {r["mode"]}. {r["goal"]}',f'Commande éclairage : {lp["controlId"]} ; {len(lp["lamps"])} lampes existantes. Circuit service conservé au retour.',json.dumps({'exits':r['exits'],'solids':r['solids'],'props':r['props']},ensure_ascii=False,indent=2)]
body+='</div><h2>Recette minimale d’une pièce</h2><p>Couper à portée, interrompre, recommencer, viser une silhouette et une cloison opaque, tester le verre, éteindre la torche, provoquer un bruit, laisser la piste se poursuivre, vérifier les tirs de couverture, exporter à mi-geste, reprendre en pause et revenir dans la même pièce. Le Codex ne remplace pas cette exécution.</p>'
js='''<script>const f=document.querySelector('#filter');f.oninput=()=>{let n=0;for(const r of document.querySelectorAll('.room')){const show=r.dataset.search.includes(f.value.toLowerCase());r.classList.toggle('hide',!show);if(show)n++;}document.querySelector('#filter-note').textContent=n+' lieux affichés';};</script>'''
(R/'CODEX_LEVEL_DESIGN_V111.html').write_text(page('Aliens V111 — Codex Dans le noir',body,js));(R/'CODEX_LEVEL_DESIGN_V111.md').write_text('\n\n'.join(md)+'\n')
selection=[('35_coupure_electrique.png','Préparer une coupure au pupitre'),('36_operations_obscurite.png','Operations dans le noir'),('37_piste_dans_le_noir.png','La poursuite continue sans lampe'),('38_faisceau_contact.png','Reprendre une orientation de torche'),('39_faisceau_cloison.png','Un cône relié aux volumes opaques'),('40_retour_lampes.png','Revenir puis rétablir le service'),('41_defense_nocturne.png','La défense dans l’obscurité'),('42_eclairage_paysage.png','Les instruments restent hors terrain'),('43_repli_circuits.png','Toute l’équipe au repli'),('30_sas_soude.png','Les fortifications V110 restent fonctionnelles')]
by={c['file']:c for c in B['captures']}
def picture(file,title):
 c=by[file];raw=(R/'report/captures-v111'/file).read_bytes();assert raw.startswith(b'\x89PNG\r\n\x1a\n');return f'<figure><h3>{e(title)}</h3><img loading="lazy" src="data:image/png;base64,{base64.b64encode(raw).decode()}" alt="{e(title)} — capture directe du jeu V111"><figcaption>{e(c["origin"])}. <strong>{e(file)}</strong> : PNG brut de Chromium, non retouché. Aucun concept généré ni dessin reconstruit après exécution.</figcaption></figure>'
body='<p class="kicker">ALIENS V111 / rapport de livraison</p><h1>Dans le noir</h1><p class="lead">Couper les lampes donne une occasion de se décaler. Cela ne supprime pas la menace qui vous a entendu.</p>'+metrics([(node,'tests Node réussis'),(len(B['tests']),'contrôles navigateur'),(6,'opérations terminées'),(len(B['captures']),'captures brutes')])
body+='<nav><a href="JOUER_ALIENS_V111.html">Jouer V111</a><a href="CODEX_LEVEL_DESIGN_V111.html">Codex de level design</a><a href="#preuves">Recette</a><a href="#limites">Périmètre</a></nav><div class="callout">Suite de la branche autonome V110, pas une fusion native. Le rapport embarque les octets exacts des images Chromium. Les scènes tardives reprennent des exports non modifiés de parcours complets puis utilisent les gestes de l’interface indiqués dans leur légende.</div>'
body+='<h2>Un éclairage utile au jeu</h2><p>Les huit commandes locales réemploient les treize lampes déjà présentes. K ou E au pupitre prépare une manœuvre de 0,95 seconde. Le booléen de circuit du monde pilote le rendu et la reconnaissance ; le relais principal et les sas restent indépendants. La torche L expose les cibles éclairées, mais son porteur l’est également.</p><p>Les contacts proches à 120 unités ou moins restent perceptibles en ligne de vue. Plus loin, la lumière devient nécessaire. Le bruit des tirs, le diagnostic et la mémoire de poursuite continuent à guider les Xénos. Les balles gardent leur trajectoire physique même si une cible n’est pas visible.</p>'
for f,t in selection:body+=picture(f,t)
body+='<h2 id="preuves">Ce qui a été exécuté</h2>'+table(['Recette','Résultat','Portée'],[['Tests Node',node,'343 hérités + 65 nouveaux tests dirigés'],['Navigateur',len(B['tests']),'148 contrôles hérités réexécutés + 39 contrôles éclairage'],['Parcours complets',6,'Direct, service, deux logistiques, brèche et noir'],['Captures',len(B['captures']),str(len(selection))+' embarquées sans modification']])
body+='<h3>Parcours nocturne depuis l’insertion</h3><p>Le pilote utilise déplacements, actions, visée, lampes et ordres publics. Il lit les positions et chemins pour décider des entrées, mais ne réécrit pas les vies, les coordonnées, les chargeurs, les circuits ou les objectifs. Deux rechargements viennent de ses propres exports valides. Les tests dirigés qui préparent des états sont comptés séparément.</p>'
body+=table(['Entrées / sous-pas','Temps simulé','Franchissements ennemis','Manœuvres électriques','État final'],[[D['inputs'],f"{D['elapsed']:.3f} s",D['enemyTransfers'],D['lighting']['metrics']['completed'],'repli confirmé']])
body+=table(['Membre','PV finaux','Munitions'],[[a['id'],a['hp'],a['ammo']] for a in D['team']])
body+='<p>Six franchissements ne signifient pas six créatures nouvelles. Le circuit d’Operations est rétabli au retour, celui des sentinelles reste coupé. La sentinelle passe de 120 à 116 cartouches dans cette dernière défense. Hudson rentre blessé, pas remis automatiquement à neuf. Les 100,225 secondes simulées ne sont pas une estimation de temps pour un joueur humain.</p>'
body+='<h2 id="limites">Limites explicites</h2><p>Huit inspections et sept lieux reliés conservés, pas de pièce, objectif obligatoire, ennemi ou sprite de production supplémentaire. La branche reste autonome ; aucun raccord aux 64 salles natives, push ou déploiement n’est déclaré. Le final Reine/P-5000 du film n’est pas remplacé.</p><p>Éclairage simplifié en 2D : l’alimentation de service est un état global par pièce, pas un réseau électrique fil par fil. La torche utilise un cône de visibilité occulté, pas une illumination volumétrique 3D. Pas de batterie finie, de sources mobiles par allié ni de propagation lumineuse entre pièces. Les flashs de rendu sont approximés localement ; la reconnaissance utilise toujours l’occlusion du monde. Les tirs restent locaux et les transferts entre pièces discrets.</p><p>Les viewports sont émulés. Le document est testé depuis ses octets exacts avec le chargeur Blob non modifié. Les niveaux artistiques et les performances d’un GPU cible ne sont pas certifiés.</p>'
body+='<h2>Provenance</h2><p class="small">Archive V110 source : ef3c6ce0db9d561314f2b40ea45581c44ec503a24d3dd28bf6b0bd70614acdce<br>HTML V111 : '+B['htmlSha256']+'<br>Contrat : '+C['contract']+'</p>'
(R/'RAPPORT_ILLUSTRE_V111.html').write_text(page('Aliens V111 — Rapport illustré Dans le noir',body))
(R/'report/report-selection-v111.json').write_text(json.dumps({'captured':len(B['captures']),'embedded':len(selection),'rules':len(rules),'files':[x[0] for x in selection],'rawImageBytesUnchanged':True},ensure_ascii=False,indent=2))
print(json.dumps({'codexRooms':len(C['rooms']),'rules':len(rules),'embedded':len(selection),'captures':len(B['captures'])}))
